/* From Uiverse.io by fanishah - Tags: loader */
.__UIV_SCOPE__ .center {
  height: 50px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .wave {
  width: 6px;
  height: 50px;
  background: linear-gradient(45deg, cyan, #fff);
  margin: 10px;
  animation: wave 1s linear infinite;
  border-radius: 20px;
}

.__UIV_SCOPE__ .wave:nth-child(2) {
  animation-delay: 0.1s;
}

.__UIV_SCOPE__ .wave:nth-child(3) {
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .wave:nth-child(4) {
  animation-delay: 0.3s;
}

.__UIV_SCOPE__ .wave:nth-child(5) {
  animation-delay: 0.4s;
}

.__UIV_SCOPE__ .wave:nth-child(6) {
  animation-delay: 0.5s;
}

.__UIV_SCOPE__ .wave:nth-child(7) {
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .wave:nth-child(8) {
  animation-delay: 0.7s;
}

.__UIV_SCOPE__ .wave:nth-child(9) {
  animation-delay: 0.8s;
}

.__UIV_SCOPE__ .wave:nth-child(10) {
  animation-delay: 0.9s;
}

@keyframes wave {
  0% {
    transform: scale(0);
  }

  50% {
    transform: scale(1);
  }

  100% {
    transform: scale(0);
  }
}
